const BRAND = {r:3/255,g:115/255,b:243/255,a:1}; // #0373F3
const DARK = {r:15/255,g:23/255,b:42/255,a:1};
const GRAY = {r:0.45,g:0.5,b:0.58,a:1};
const WHITE = {r:1,g:1,b:1,a:1};
const SURF = {r:247/255,g:249/255,b:253/255,a:1};
const FW = 402, FH = 874;

function makeText(parent, str, x, y, size, family, weight, color, align="left") {
  const t = figma.createText();
  t.fontName = {family, style:weight};
  t.characters = str;
  t.fontSize = size;
  t.x = x; t.y = y;
  t.fills = [{type:"SOLID", color}];
  t.textAlignHorizontal = align;
  parent.appendChild(t);
  return t;
}
async function addMedia(id, parent, x, y, w, h){
  const n = figma.getNodeById(id);
  if(!n) throw new Error("media missing "+id);
  const c = n.clone();
  parent.appendChild(c);
  c.x = x; c.y = y;
  if(w&&h){ c.resize(w,h); }
  return c;
}
function addRect(parent, x, y, w, h, color, r=0){
  const rct = figma.createRectangle();
  rct.x=x; rct.y=y; rct.resize(w,h);
  rct.fills=[{type:"SOLID", color}];
  if(r) rct.cornerRadius = r;
  parent.appendChild(rct);
  return rct;
}

